def looks_like_tool_start(event: dict[str, Any]) -> bool:
    status = str(event.get("status", "")).lower()
    event_type = str(event.get("type", "")).lower()
    phase = str(event.get("phase", "")).lower()
    if any(marker in event_type for marker in ("tool.execute", "tool_call", "tool.call", "tool_use")):
        return not any(done in event_type for done in ("after", "result", "complete", "finish"))
    return status in {"started", "running", "pending"} or phase in {"start", "before"}

def _detect_system_cuda_major() -> Optional[int]:
    try:
        proc = subprocess.run(
            ["nvidia-smi"],
            capture_output=True,
            text=True,
            check=False,
        )
        text = (proc.stdout or "") + "\n" + (proc.stderr or "")
        m = re.search(r"CUDA Version:\s*([0-9]+\.[0-9]+)", text)
        if m:
            return _major_from_version_string(m.group(1))
    except Exception:
        pass

    try:
        proc = subprocess.run(
            ["nvcc", "--version"],
            capture_output=True,
            text=True,
            check=False,
        )
        text = (proc.stdout or "") + "\n" + (proc.stderr or "")
        m = re.search(r"release\s+([0-9]+\.[0-9]+)", text)
        if m:
            return _major_from_version_string(m.group(1))
    except Exception:
        pass

    return None

