def _jax_step(trainable_vars, non_trainable_vars, optimizer_vars, td, y):
    def _loss_and_state(tv, ntv):
        logits, new_ntv = model.stateless_call(tv, ntv, td, training=True)
        loss = loss_fn(y, logits)
        return loss, new_ntv

    (loss, new_ntv), grads = jax.value_and_grad(
        _loss_and_state, has_aux=True, allow_int=True
    )(
        trainable_vars, non_trainable_vars
    )
    new_tv, new_ov = optimizer.stateless_apply(optimizer_vars, grads, trainable_vars)
    return loss, new_tv, new_ntv, new_ov

def extract_judge_json(raw: str) -> dict[str, object]:
    candidates: list[str] = []
    for line in raw.splitlines():
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(event, dict):
            part = event.get("part")
            text = part.get("text") if isinstance(part, dict) else event.get("text")
            if isinstance(text, str):
                candidates.extend(json_candidates_from_text(text))
    candidates.extend(json_candidates_from_text(raw))
    for candidate in reversed(candidates):
        try:
            value = json.loads(candidate)
        except json.JSONDecodeError:
            continue
        if isinstance(value, dict) and "score" in value:
            return value
    return {}

def collect_usage(event: dict[str, Any], result: OpencodeRunResult) -> None:
    usage = event.get("usage")
    if not isinstance(usage, dict):
        message = event.get("message")
        usage = message.get("usage") if isinstance(message, dict) else None
    if not isinstance(usage, dict):
        part = event.get("part")
        usage = part.get("tokens") if isinstance(part, dict) else None
    if not isinstance(usage, dict):
        return
    input_tokens = first_int(usage, "input", "input_tokens", "prompt_tokens", "prompt")
    output_tokens = first_int(usage, "output", "output_tokens", "completion_tokens", "completion")
    total_tokens = first_int(usage, "total", "total_tokens", "tokens")
    cost = first_float(usage, "cost", "cost_usd")
    if input_tokens is not None:
        result.tokens_input = (result.tokens_input or 0) + input_tokens
    if output_tokens is not None:
        result.tokens_output = (result.tokens_output or 0) + output_tokens
    if total_tokens is not None:
        result.tokens_total = (result.tokens_total or 0) + total_tokens
    if cost is not None:
        result.cost_usd = (result.cost_usd or 0.0) + cost

def combined_status(opencode_returncode: int, validation: ValidationResult, judge: JudgeResult) -> str:
    if opencode_returncode == 124:
        return "timeout"
    if opencode_returncode != 0:
        return "error"
    if validation.status not in {"passed", "not_run"}:
        return "failed"
    if judge.enabled and judge.passed is False:
        return "judge_failed"
    return "passed"

def make_node_mlp(
    units,
    edge_message_input_shape=None,
    node_state_input_shape=None,
    global_state_input_shape=None,
    node_emb_size=None,
    use_global_input=False,
    use_edge_state_agg_input=True,
    graph_indep=False,
    use_node_state_input=True,
    activation="relu",
    **kwargs,
):

    if use_edge_state_agg_input and graph_indep:
        raise Exception(
            "Requested a GraphIndep graphnet node function but speciffied use of node input! This is inconsistent."
        )
    if use_global_input and graph_indep:
        raise Exception(
            "Requested a GraphIndep graphnet node function but speciffied use of global input! This is inconsistent."
        )

    all_inputs = []
    if use_node_state_input:
        node_state_in = Input(
            shape=_maybe_make_tuple(node_state_input_shape),
            name=NodeInput.NODE_STATE.value,
        )
        all_inputs.append(node_state_in)

    if use_edge_state_agg_input:
        agg_edge_state_in = Input(
            shape=_maybe_make_tuple(edge_message_input_shape),
            name=NodeInput.EDGE_AGG_STATE.value,
        )
        all_inputs.append(agg_edge_state_in)

    if use_global_input:
        global_state_in = Input(
            shape=_maybe_make_tuple(global_state_input_shape),
            name=NodeInput.GLOBAL_STATE.value,
        )
        all_inputs.append(global_state_in)

    kwargs["model_name"] = "node_fn-model"
    return make_mlp(units, all_inputs, node_emb_size, activation=activation, **kwargs)

