        possible_global_inputs = [
            "node_state_agg",
            "edge_state_agg",
            "global_state",
        ]
        for nn in possible_global_inputs:
            for g_ in global_fn_inputs:
                if nn in g_:
                    self.global_input_dict.update({nn: g_})

