    self.head = keras.layers.Dense(1)

def node_block(
    self,
    edges=None,
    nodes=None,
    senders=None,
    receivers=None,
    n_edges=None,
    n_nodes=None,
    global_attr=None,
    global_reps_for_edges=None,
    global_reps_for_nodes=None,
    n_graphs=None,
):
    # 2) Aggregate the messages (unsorted segment sums etc):
    node_inputs = OrderedDict()
    # 3) Compute node function:
    if NodeInput.NODE_STATE.value in self.node_input_dict.keys():
        node_inputs.update({NodeInput.NODE_STATE.value: nodes})

    if NodeInput.GLOBAL_STATE.value in self.node_input_dict.keys():
        node_inputs.update(
            {
                NodeInput.GLOBAL_STATE.value: backend_ops.gather(
                    global_attr, global_reps_for_nodes
                )
            }
        )

    if NodeInput.EDGE_AGG_STATE.value in self.node_input_dict.keys():
        if self.has_seg_aggregator_edge_to_global:
            max_seq = backend_ops.first_dim(nodes)
            edge_to_nodes_messages = self.edge_aggregation_function_seg(
                edges, receivers, max_seq
            )
        else:
            raise Exception("Not Implemented!")
        node_inputs.update({NodeInput.EDGE_AGG_STATE.value: edge_to_nodes_messages})

    nodes = self.node_function(node_inputs)

    return nodes

def call(self, d, training=False):
    out = d.copy()
    out["nodes"] = self.input_dropout(out["nodes"], training=training)
    if self.use_shortcut:
        shortcut = None
    for conv_idx, conv in enumerate(self.convs):
        prev_nodes = out["nodes"]
        out = conv(out, training=training)
        if self.residual:
            if self.residual_projection:
                proj = self.residual_projections[conv_idx]
                skip = proj(prev_nodes)
            else:
                skip = prev_nodes
                if prev_nodes.shape[-1] != out["nodes"].shape[-1]:
                    skip = None
            if skip is not None:
                out = out.copy()
                out["nodes"] = out["nodes"] + skip
        out_nodes = self.dropout(out["nodes"], training=training)
        # make shortcut connections of all layers to 
        # the end layer (skip the end layer)
        if self.use_shortcut and conv_idx < (len(self.convs)-1):
            contribution = out_nodes / len(self.convs)
            if shortcut is None:
                shortcut = contribution
            else:
                shortcut = shortcut + contribution
        out = out.copy()
        out["nodes"] = out_nodes

    if self.use_shortcut and shortcut is not None:
        out['nodes'] = out['nodes'] + shortcut
    out = out.copy()
    out["nodes"] = self.head(out["nodes"])
    return out

def get_graph(self, graph_index):
    """Extract a single :class:`Graph` from this batch.

    Args:
        graph_index: Zero-based index of the graph to extract.

    Returns:
        A new :class:`Graph` object containing copied node/edge features.
    """
    assert graph_index >= 0
    if graph_index > self.n_graphs:
        raise ValueError(
            "The provided index is larger than the available graphs in this GraphTuple object."
        )

    def get_start_stop_index(sizes_list, index):
        return np.cumsum([0, *sizes_list[0 : index + 1]])[-2:]

    start_idx_nodes, end_idx_nodes = get_start_stop_index(self.n_nodes, graph_index)
    start_idx_edges, end_idx_edges = get_start_stop_index(self.n_edges, graph_index)
    nodes_attrs = self.nodes[start_idx_nodes:end_idx_nodes]
    senders, receivers, edge_attr = [
        v[start_idx_edges:end_idx_edges]
        for v in [self.senders, self.receivers, self.edges]
    ]
    senders = senders - start_idx_nodes
    receivers = receivers - start_idx_nodes
    nodes = [Node(backend_ops.expand_dims(node_attr, axis=0)) for node_attr in nodes_attrs]
    edges = [
        Edge(
            backend_ops.expand_dims(edge_attr_tensor, axis=0),
            nodes[node_from_idx],
            nodes[node_to_idx],
        )
        for edge_attr_tensor, node_from_idx, node_to_idx in zip(
            edge_attr, senders, receivers
        )
    ]
    if self.has_global:
        global_attr = self.global_attr[graph_index]
    else:
        global_attr = None
    return Graph(nodes, edges, global_attr=global_attr)

def call(self, td, training=False):
    out = self.gcn(td, training=training)
    return out["nodes"]

