def update_reps_for_globals(self):
    """Build helper vectors mapping nodes/edges to graph indices."""
    global_reps_for_edges = []  # <- used to cast the global tensor to a compatible size for the edges.
    for k, e in enumerate(self.n_edges):
        global_reps_for_edges.extend([k] * int(e))
    self._global_reps_for_edges = global_reps_for_edges

    global_reps_for_nodes = []  # <- similarly for nodes:
    for k, e in enumerate(self.n_nodes):
        global_reps_for_nodes.extend([k] * int(e))

    self._global_reps_for_nodes = global_reps_for_nodes

#!/usr/bin/env python3
"""Verify TensorFlow and PyTorch are installed with GPU support."""

from __future__ import annotations

import json
import subprocess
import sys


def _run_probe(code: str) -> tuple[int, str, str]:
    proc = subprocess.run(
        [sys.executable, "-c", code],
        capture_output=True,
        text=True,
    )
    return proc.returncode, proc.stdout, proc.stderr


def check_torch() -> bool:
    code = """
import json
import torch
payload = {
  'version': torch.__version__,
  'cuda_available': bool(torch.cuda.is_available()),
  'device_count': int(torch.cuda.device_count()) if torch.cuda.is_available() else 0,
  'devices': [],
}
if payload['cuda_available']:
    for i in range(payload['device_count']):
        payload['devices'].append({
            'index': i,
            'name': torch.cuda.get_device_name(i),
            'capability': '.'.join(map(str, torch.cuda.get_device_capability(i))),
        })
print(json.dumps(payload))
"""
    rc, out, err = _run_probe(code)
    if rc != 0:
        print("[torch] import/probe failed")
        if err.strip():
            print(err.strip())
        return False

    payload = json.loads(out.strip())
    print(f"[torch] version: {payload['version']}")
    print(f"[torch] cuda available: {payload['cuda_available']}")
    if payload["cuda_available"]:
        print(f"[torch] gpu count: {payload['device_count']}")
        for d in payload["devices"]:
            print(
                f"[torch] gpu[{d['index']}]: {d['name']} capability={d['capability']}"
            )
    return bool(payload["cuda_available"])


def check_tensorflow() -> bool:
    code = """
import json
import tensorflow as tf
gpus = tf.config.list_physical_devices('GPU')
payload = {
  'version': tf.__version__,
  'gpu_available': len(gpus) > 0,
  'gpus': [g.name for g in gpus],
}
print(json.dumps(payload))
"""
    rc, out, err = _run_probe(code)
    if rc != 0:
        print("[tensorflow] import/probe failed")
        if err.strip():
            print(err.strip())
        return False

    payload = json.loads(out.strip())
    print(f"[tensorflow] version: {payload['version']}")
    print(f"[tensorflow] gpu available: {payload['gpu_available']}")
    for i, name in enumerate(payload["gpus"]):
        print(f"[tensorflow] gpu[{i}]: {name}")
    if err.strip():
        print("[tensorflow] probe stderr:")
        print(err.strip())
    return bool(payload["gpu_available"])


def main() -> int:
    print("Checking GPU support for torch and tensorflow...\n")
    torch_ok = check_torch()
    print("")
    tf_ok = check_tensorflow()
    print("")

    if torch_ok and tf_ok:
        print("PASS: torch and tensorflow both have GPU support.")
        return 0

    if not torch_ok and not tf_ok:
        print("FAIL: neither torch nor tensorflow reports GPU support.")
    elif not torch_ok:
        print("FAIL: torch does not report GPU support.")
    else:
        print("FAIL: tensorflow does not report GPU support.")
        print(
            "Hint: try running via scripts/run_with_tf_gpu to expose pip-installed CUDA/cuDNN libs."
        )
    return 1


if __name__ == "__main__":
    raise SystemExit(main())

"""Thin backend-ops facade over Keras 3 ops.

Most functions are direct wrappers around ``keras.ops`` so core library code can
avoid binding directly to TensorFlow symbols.

Current fallback matrix:
- ``segment_sum``: native ``keras.ops``
- ``segment_max``: native ``keras.ops``
- ``segment_mean``: composed from ``segment_sum`` + ``bincount``
- ``segment_min``: TensorFlow fallback only (until ``keras.ops.segment_min`` exists)

This module should stay intentionally small and declarative.
"""

import keras
import warnings


def active_backend():
    """Return the active Keras backend name."""
    return keras.backend.backend()


def has_native_segment_min():
    """Return whether the current Keras backend exposes ``segment_min``."""
    return hasattr(keras.ops, "segment_min")


_SEGMENT_MIN_EMULATION_WARNED = False


def _warn_segment_min_emulation():
    global _SEGMENT_MIN_EMULATION_WARNED
    if not _SEGMENT_MIN_EMULATION_WARNED:
        warnings.warn(
            "Using emulated segment_min via -segment_max(-x). "
            "This may be slower or numerically different than a native backend op.",
            RuntimeWarning,
            stacklevel=2,
        )
        _SEGMENT_MIN_EMULATION_WARNED = True


def _as_int_tensor(x):
    return keras.ops.cast(keras.ops.convert_to_tensor(x), "int32")


def gather(params, indices, axis=0):
    return keras.ops.take(params, _as_int_tensor(indices), axis=axis)


def concat(xs, axis=-1):
    return keras.ops.concatenate(xs, axis=axis)


def first_dim(x):
    return keras.ops.shape(x)[0]


def zeros_like(x):
    return keras.ops.zeros_like(x)


def zeros(shape, dtype="float32"):
    return keras.ops.zeros(shape, dtype=dtype)


def stack(xs, axis=0):
    return keras.ops.stack(xs, axis=axis)


def squeeze(x, axis=None):
    return keras.ops.squeeze(x, axis=axis)


def expand_dims(x, axis=0):
    return keras.ops.expand_dims(x, axis=axis)


def convert_to_tensor(x, dtype=None):
    return keras.ops.convert_to_tensor(x, dtype=dtype)


def identity(x):
    return x + 0


def shape(x):
    return keras.ops.shape(x)


def is_tensor(x):
    return keras.ops.is_tensor(x)


def reduce_all(x, axis=None):
    return keras.ops.all(x, axis=axis)


def reduce_mean(x, axis=0):
    return keras.ops.mean(x, axis=axis)


def reduce_sum(x, axis=0):
    return keras.ops.sum(x, axis=axis)


def reduce_max(x, axis=0):
    return keras.ops.max(x, axis=axis)


def reduce_min(x, axis=0):
    return keras.ops.min(x, axis=axis)


def segment_sum(values, indices, num_groups):
    return keras.ops.segment_sum(values, _as_int_tensor(indices), num_groups)


def segment_max(values, indices, num_groups):
    return keras.ops.segment_max(values, _as_int_tensor(indices), num_groups)


def _present_segment_mask(indices, num_groups, dtype):
    indices = _as_int_tensor(indices)
    present = keras.ops.segment_max(keras.ops.ones_like(indices), indices, num_groups)
    present = keras.ops.clip(present, 0, 1)
    present = keras.ops.cast(present, dtype)
    return keras.ops.expand_dims(present, axis=-1)


def _zero_absent_segments(reduced, indices, num_groups):
    present = _present_segment_mask(indices, num_groups, reduced.dtype)
    zeros = keras.ops.zeros_like(reduced)
    return keras.ops.where(present > 0, reduced, zeros)


def segment_max_or_zero(values, indices, num_groups):
    reduced = segment_max(values, indices, num_groups)
    return _zero_absent_segments(reduced, indices, num_groups)


def segment_mean(values, indices, num_groups):
    indices = _as_int_tensor(indices)
    sums = segment_sum(values, indices, num_groups)
    one_col = keras.ops.ones((keras.ops.shape(indices)[0], 1), dtype=sums.dtype)
    counts = segment_sum(one_col, indices, num_groups)
    counts = keras.ops.maximum(counts, keras.ops.ones_like(counts))
    return sums / counts


def segment_min(values, indices, num_groups):
    indices = _as_int_tensor(indices)
    if has_native_segment_min():
        return keras.ops.segment_min(values, indices, num_groups)
    if active_backend() == "tensorflow":
        import tensorflow as tf

        return tf.math.unsorted_segment_min(values, indices, num_groups)
    _warn_segment_min_emulation()
    return -segment_max(-values, indices, num_groups)


def segment_min_or_zero(values, indices, num_groups):
    reduced = segment_min(values, indices, num_groups)
    return _zero_absent_segments(reduced, indices, num_groups)

"""Generate the packaged tf_gnns agent-skill API index."""

from __future__ import annotations

import argparse
import ast
import json
import re
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
PACKAGE = ROOT / "tf_gnns"
OUT = PACKAGE / "agent_skill" / "api_index.json"


def _references_files() -> list[Path]:
    return sorted((PACKAGE / "agent_skill" / "references").glob("*.md"))


def _public_names() -> list[str]:
    names: set[str] = set()
    # Root package __all__
    module = ast.parse((PACKAGE / "__init__.py").read_text(encoding="utf-8"))
    for node in module.body:
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id == "__all__":
                    names.update(ast.literal_eval(node.value))
    # Submodule __all__ (e.g. tf_gnns.models exports GCNv2), but only keep
    # names that are referenced in the reference docs so internal runtime
    # helpers (e.g. maybe_patch_ld_library_path_for_tensorflow) do not leak in.
    referenced_docs = "\n".join(p.read_text(encoding="utf-8") for p in _references_files())
    for subinit in sorted(PACKAGE.rglob("__init__.py")):
        if subinit == PACKAGE / "__init__.py":
            continue
        try:
            submod = ast.parse(subinit.read_text(encoding="utf-8"))
        except SyntaxError:
            continue
        for node in submod.body:
            if isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Name) and target.id == "__all__":
                        for name in ast.literal_eval(node.value):
                            if name.startswith("_"):
                                continue
                            pattern = rf"(?<![A-Za-z0-9_]){re.escape(name)}(?![A-Za-z0-9_])"
                            if re.search(pattern, referenced_docs):
                                names.add(name)
    # Filter out private names (underscore-prefixed)
    return sorted(n for n in names if not n.startswith("_"))


def _signature(name: str, node: ast.AST) -> str:
    if isinstance(node, ast.ClassDef):
        init = next((item for item in node.body if isinstance(item, ast.FunctionDef) and item.name == "__init__"), None)
        if init is None:
            return f"{name}(...)"
        args = init.args
    elif isinstance(node, ast.FunctionDef):
        args = node.args
    else:
        return name

    parts = []
    positional = list(args.posonlyargs) + list(args.args)
    defaults = [None] * (len(positional) - len(args.defaults)) + list(args.defaults)
    for arg, default in zip(positional, defaults):
        if arg.arg == "self":
            continue
        text = arg.arg
        if default is not None:
            text += f"={ast.unparse(default)}"
        parts.append(text)
    if args.vararg:
        parts.append("*" + args.vararg.arg)
    elif args.kwonlyargs:
        parts.append("*")
    for arg, default in zip(args.kwonlyargs, args.kw_defaults):
        text = arg.arg
        if default is not None:
            text += f"={ast.unparse(default)}"
        parts.append(text)
    if args.kwarg:
        parts.append("**" + args.kwarg.arg)
    return f"{name}({', '.join(parts)})"


def _summary(docstring: str | None) -> str:
    if not docstring:
        return "No docstring summary."
    for line in docstring.strip().splitlines():
        line = line.strip()
        if line:
            return line
    return "No docstring summary."


def _returns(docstring: str | None) -> str:
    if not docstring or "Returns:" not in docstring:
        return ""
    lines = docstring.splitlines()
    for index, line in enumerate(lines):
        if line.strip() == "Returns:":
            collected = []
            for follow in lines[index + 1 :]:
                stripped = follow.strip()
                if not stripped:
                    continue
                if stripped.endswith(":") and not follow.startswith((" ", "\t")):
                    break
                collected.append(stripped)
                if len(" ".join(collected)) > 140:
                    break
            return " ".join(collected)
    return ""


def _topic(name: str, module: str) -> str:
    lower = name.lower()
    if lower in {"node", "edge", "graph", "graphtuple"} or "graph_tuple" in lower:
        return "graphs"
    if "gcn" in lower:
        return "gcn"
    if "backend" in module:
        return "backends"
    if "graphnet" in lower or "graphindep" in lower or "mlp" in lower or "agg" in lower:
        return "graphnets"
    return "quickstart"


def _examples() -> dict[str, str]:
    examples: dict[str, str] = {}
    for path in (PACKAGE / "agent_skill" / "references").glob("*.md"):
        text = path.read_text(encoding="utf-8")
        code = "\n".join(re.findall(r"```python\n(.*?)```", text, flags=re.DOTALL))
        for name in _public_names():
            pattern = rf"(?<![A-Za-z0-9_]){re.escape(name)}(?![A-Za-z0-9_])"
            if re.search(pattern, code):
                examples.setdefault(name, path.stem)
    return examples


def build_index() -> dict[str, object]:
    public = set(_public_names())
    examples = _examples()
    entries = []
    for path in sorted(PACKAGE.rglob("*.py")):
        if "agent_skill" in path.parts or path.name == "agent_docs.py":
            continue
        module_name = ".".join(path.relative_to(ROOT).with_suffix("").parts)
        module = ast.parse(path.read_text(encoding="utf-8"))
        for node in module.body:
            if not isinstance(node, (ast.ClassDef, ast.FunctionDef)) or node.name not in public:
                continue
            docstring = ast.get_docstring(node)
            entries.append(
                {
                    "name": node.name,
                    "import": f"from {module_name} import {node.name}",
                    "signature": _signature(node.name, node),
                    "summary": _summary(docstring),
                    "returns": _returns(docstring),
                    "source": f"{path.relative_to(ROOT)}:{node.lineno}",
                    "topic": _topic(node.name, module_name),
                    "example": examples.get(node.name, ""),
                }
            )
    entries.sort(key=lambda entry: entry["name"].lower())
    return {"generated_by": "scripts/generate_agent_api_index.py", "entries": entries}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="Fail if api_index.json is stale")
    args = parser.parse_args(argv)
    index = build_index()
    rendered = json.dumps(index, indent=2, sort_keys=True) + "\n"
    if args.check:
        current = OUT.read_text(encoding="utf-8") if OUT.exists() else ""
        if current != rendered:
            raise SystemExit("api_index.json is stale; run: python scripts/generate_agent_api_index.py")
        return 0
    OUT.write_text(rendered, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import types

from tf_gnns.commons.tensorflow import runtime_cuda_path as rcp


def test_major_from_version_string_parses_and_rejects():
    assert rcp._major_from_version_string("12.4") == 12
    assert rcp._major_from_version_string("CUDA 13.0") == 13
    assert rcp._major_from_version_string("unknown") is None


def test_detect_system_cuda_major_from_nvidia_smi(monkeypatch):
    def fake_run(cmd, capture_output, text, check):
        del capture_output, text, check
        if cmd == ["nvidia-smi"]:
            return types.SimpleNamespace(stdout="CUDA Version: 13.1", stderr="")
        return types.SimpleNamespace(stdout="", stderr="")

    monkeypatch.setattr(rcp.subprocess, "run", fake_run)
    assert rcp._detect_system_cuda_major() == 13


def test_detect_system_cuda_major_falls_back_to_nvcc(monkeypatch):
    def fake_run(cmd, capture_output, text, check):
        del capture_output, text, check
        if cmd == ["nvidia-smi"]:
            raise RuntimeError("missing")
        if cmd == ["nvcc", "--version"]:
            return types.SimpleNamespace(stdout="Cuda compilation tools, release 12.8", stderr="")
        return types.SimpleNamespace(stdout="", stderr="")

    monkeypatch.setattr(rcp.subprocess, "run", fake_run)
    assert rcp._detect_system_cuda_major() == 12


def test_discover_pip_nvidia_lib_paths_deduplicates(monkeypatch):
    monkeypatch.setattr(rcp.site, "getsitepackages", lambda: ["/a", "/b"])

    def fake_glob(pattern):
        if pattern.startswith("/a"):
            return ["/a/nvidia/cublas/lib", "/a/nvidia/cudnn/lib"]
        return ["/a/nvidia/cublas/lib", "/b/nvidia/cusolver/lib"]

    monkeypatch.setattr(rcp.glob, "glob", fake_glob)
    assert rcp._discover_pip_nvidia_lib_paths() == [
        "/a/nvidia/cublas/lib",
        "/a/nvidia/cudnn/lib",
        "/b/nvidia/cusolver/lib",
    ]


def test_patch_ld_library_path_success(monkeypatch):
    monkeypatch.setattr(rcp, "_PATCH_ALREADY_RUN", False)
    monkeypatch.delenv(rcp._PATCH_MARKER_ENV, raising=False)
    monkeypatch.setenv("LD_LIBRARY_PATH", "/usr/lib:/opt/lib")
    monkeypatch.setattr(rcp, "_detect_system_cuda_major", lambda: 13)
    monkeypatch.setattr(rcp, "_detect_tf_build_cuda_major", lambda: 12)
    monkeypatch.setattr(rcp, "_discover_pip_nvidia_lib_paths", lambda: ["/x/lib", "/y/lib"])

    changed = rcp.maybe_patch_ld_library_path_for_tensorflow()
    assert changed is True
    assert rcp._PATCH_MARKER_ENV in rcp.os.environ
    assert rcp.os.environ["LD_LIBRARY_PATH"] == "/x/lib:/y/lib:/usr/lib:/opt/lib"


def test_patch_ld_library_path_noop_paths(monkeypatch):
    monkeypatch.setattr(rcp, "_PATCH_ALREADY_RUN", False)
    monkeypatch.delenv(rcp._PATCH_MARKER_ENV, raising=False)
    monkeypatch.setattr(rcp, "_detect_system_cuda_major", lambda: 12)
    monkeypatch.setattr(rcp, "_detect_tf_build_cuda_major", lambda: 12)
    monkeypatch.setattr(rcp, "_discover_pip_nvidia_lib_paths", lambda: ["/x/lib"])
    assert rcp.maybe_patch_ld_library_path_for_tensorflow() is False


def test_patch_ld_library_path_idempotent(monkeypatch):
    monkeypatch.setattr(rcp, "_PATCH_ALREADY_RUN", False)
    monkeypatch.setenv(rcp._PATCH_MARKER_ENV, "1")
    assert rcp.maybe_patch_ld_library_path_for_tensorflow() is False

#!/usr/bin/env python3
import json
import sys
import xml.etree.ElementTree as ET
from pathlib import Path


def badge_color(coverage_pct: int) -> str:
    if coverage_pct >= 90:
        return "brightgreen"
    if coverage_pct >= 80:
        return "green"
    if coverage_pct >= 70:
        return "yellowgreen"
    if coverage_pct >= 60:
        return "yellow"
    if coverage_pct >= 50:
        return "orange"
    return "red"


def main() -> int:
    if len(sys.argv) != 3:
        print("Usage: update_coverage_badge.py <coverage.xml> <output.json>", file=sys.stderr)
        return 1

    coverage_xml = Path(sys.argv[1])
    out_json = Path(sys.argv[2])

    if not coverage_xml.exists():
        print(f"Coverage file not found: {coverage_xml}", file=sys.stderr)
        return 1

    root = ET.parse(coverage_xml).getroot()
    line_rate_raw = root.attrib.get("line-rate")
    if line_rate_raw is None:
        print("Coverage XML does not contain line-rate", file=sys.stderr)
        return 1

    coverage_pct = int(round(float(line_rate_raw) * 100))
    payload = {
        "schemaVersion": 1,
        "label": "coverage",
        "message": f"{coverage_pct}%",
        "color": badge_color(coverage_pct),
    }

    out_json.parent.mkdir(parents=True, exist_ok=True)
    out_json.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
    print(f"Coverage: {coverage_pct}%")
    print(f"Wrote badge data: {out_json}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Dataset loading and conversion utilities for ogbg-molhiv MPNN benchmarks."""

from __future__ import annotations

from benchmarks.ogbg_molhiv.data import DatasetSplits, load_ogbg_molhiv

import numpy as np


def validate_dataset_indexed_graphs(dataset, indices: np.ndarray, max_graphs: int = 64) -> None:
    if len(indices) == 0:
        raise ValueError("No indices provided for validation")
    check_n = min(len(indices), max_graphs)
    for i in range(check_n):
        g, y = dataset[int(indices[i])]
        if "node_feat" not in g or "edge_index" not in g:
            raise ValueError("OGB graph missing expected keys")
        if "edge_feat" not in g:
            raise ValueError("OGB graph missing edge_feat required for MPNN")
        if g["node_feat"].ndim != 2:
            raise ValueError("node_feat expected rank-2")
        if g["edge_feat"].ndim != 2:
            raise ValueError("edge_feat expected rank-2")
        if g["edge_index"].shape[0] != 2:
            raise ValueError("edge_index expected shape [2, E]")
        if int(g["edge_feat"].shape[0]) != int(g["edge_index"].shape[1]):
            raise ValueError("edge_feat length must match number of edges")
        if y is None:
            raise ValueError("label is missing")


def make_framework_samples(
    dataset,
    indices: np.ndarray,
    max_graphs: int = 32,
    include_tf: bool = True,
    include_dgl: bool = True,
):
    """Create aligned per-framework sample objects with edge features."""
    import torch
    from torch_geometric.data import Data
    dgl = None
    if include_dgl:
        import dgl  # type: ignore[no-redef]
    tf = None
    if include_tf:
        import tensorflow as tf  # type: ignore[no-redef]

    selected = indices[:max_graphs]
    tf_samples = []
    pyg_samples = []
    dgl_samples = []

    for idx in selected:
        graph, y = dataset[int(idx)]
        edge_index = graph["edge_index"]
        node_feat = graph["node_feat"].astype(np.float32)
        edge_feat = graph["edge_feat"].astype(np.float32)
        y_val = np.asarray(y, dtype=np.float32).reshape(-1)

        senders = edge_index[0].astype(np.int32)
        receivers = edge_index[1].astype(np.int32)
        n_nodes = int(graph["num_nodes"])
        n_edges = int(edge_index.shape[1])

        if include_tf:
            td = {
                "nodes": tf.convert_to_tensor(node_feat),
                "edges": tf.convert_to_tensor(edge_feat),
                "senders": tf.convert_to_tensor(senders, dtype=tf.int32),
                "receivers": tf.convert_to_tensor(receivers, dtype=tf.int32),
                "n_edges": tf.convert_to_tensor([n_edges], dtype=tf.int32),
                "n_nodes": tf.convert_to_tensor([n_nodes], dtype=tf.int32),
                "n_graphs": tf.convert_to_tensor(1, dtype=tf.int32),
                "global_attr": tf.zeros((1, 1), dtype=tf.float32),
                "global_reps_for_edges": tf.zeros((n_edges,), dtype=tf.int32),
                "global_reps_for_nodes": tf.zeros((n_nodes,), dtype=tf.int32),
            }
            tf_samples.append((td, tf.convert_to_tensor(y_val, dtype=tf.float32)))

        pyg_samples.append(
            Data(
                x=torch.tensor(node_feat, dtype=torch.float32),
                edge_index=torch.tensor(edge_index, dtype=torch.long),
                edge_attr=torch.tensor(edge_feat, dtype=torch.float32),
                y=torch.tensor(y_val, dtype=torch.float32),
            )
        )

        if include_dgl:
            dg = dgl.graph((senders, receivers), num_nodes=n_nodes)
            dg.ndata["x"] = torch.tensor(node_feat, dtype=torch.float32)
            dg.edata["edge_attr"] = torch.tensor(edge_feat, dtype=torch.float32)
            dg.ndata["batch"] = torch.zeros((n_nodes,), dtype=torch.long)
            dg.y = torch.tensor(y_val, dtype=torch.float32)
            dgl_samples.append(dg)

    return tf_samples, pyg_samples, dgl_samples


def validate_framework_sample_alignment(tf_samples, pyg_samples, dgl_samples) -> None:
    if tf_samples:
        if dgl_samples:
            if not (len(tf_samples) == len(pyg_samples) == len(dgl_samples)):
                raise ValueError("Sample count mismatch across frameworks")
        elif len(tf_samples) != len(pyg_samples):
            raise ValueError("Sample count mismatch between tf_gnns and PyG")
    elif dgl_samples and len(pyg_samples) != len(dgl_samples):
        raise ValueError("Sample count mismatch between PyG and DGL")

    if not tf_samples and dgl_samples:
        for pyg, dg in zip(pyg_samples, dgl_samples):
            if int(pyg.x.shape[0]) != int(dg.num_nodes()):
                raise ValueError("Node-count mismatch between PyG and DGL")
            if int(pyg.edge_index.shape[1]) != int(dg.num_edges()):
                raise ValueError("Edge-count mismatch between PyG and DGL")
        return
    if not tf_samples:
        return

    for idx, ((td, _), pyg) in enumerate(zip(tf_samples, pyg_samples)):
        tf_nodes = int(td["nodes"].shape[0])
        tf_edges = int(td["senders"].shape[0])
        if tf_nodes != int(pyg.x.shape[0]):
            raise ValueError("Node-count mismatch between tf_gnns and PyG")
        if tf_edges != int(pyg.edge_index.shape[1]):
            raise ValueError("Edge-count mismatch between tf_gnns and PyG")
        if dgl_samples:
            dg = dgl_samples[idx]
            if tf_nodes != int(dg.num_nodes()):
                raise ValueError("Node-count mismatch across framework samples")
            if tf_edges != int(dg.num_edges()):
                raise ValueError("Edge-count mismatch across framework samples")
        if int(td["edges"].shape[0]) != int(pyg.edge_attr.shape[0]):
            raise ValueError("Edge-feature count mismatch between tf_gnns and PyG")


__all__ = [
    "DatasetSplits",
    "load_ogbg_molhiv",
    "make_framework_samples",
    "validate_dataset_indexed_graphs",
    "validate_framework_sample_alignment",
]

"""Command-line retrieval for the packaged tf_gnns agent skill."""

from __future__ import annotations

import argparse
import json
import re
import shutil
import sys
from dataclasses import dataclass
from importlib import resources
from pathlib import Path


SKILL_PACKAGE = "tf_gnns.agent_skill"
SKILL_NAME = "tf-gnns-user-docs"


@dataclass(frozen=True)
class Topic:
    name: str
    title: str
    when: str
    path: str


TOPICS = [
    Topic("quickstart", "Quickstart", "creating a small GraphTuple and running one model", "references/quickstart.md"),
    Topic("graphs", "Graph Data", "building Node, Edge, Graph, and GraphTuple inputs", "references/graphs.md"),
    Topic("graphnets", "GraphNet Blocks", "using GraphNet factories, MPNN layers, globals, and aggregators", "references/graphnets.md"),
    Topic("gcn", "Sparse GCN", "using SparseGCNConv, SparseGCN, or GCNv2 on tensor dictionaries", "references/gcn.md"),
    Topic("backends", "Backends", "choosing TensorFlow, Torch, or JAX Keras backends", "references/backends.md"),
]


def _resource_text(path: str) -> str:
    return _skill_root().joinpath(path).read_text(encoding="utf-8")


def _skill_root():
    try:
        return resources.files(SKILL_PACKAGE)
    except ModuleNotFoundError:
        return Path(__file__).with_name("agent_skill")


def _copy_skill(destination: Path) -> None:
    try:
        root = resources.files(SKILL_PACKAGE)
    except ModuleNotFoundError:
        shutil.copytree(Path(__file__).with_name("agent_skill"), destination)
        return
    with resources.as_file(root) as skill_root:
        shutil.copytree(skill_root, destination)


def _api_index() -> list[dict[str, object]]:
    return json.loads(_resource_text("api_index.json"))["entries"]


def _topic_by_name(name: str) -> Topic:
    for topic in TOPICS:
        if topic.name == name:
            return topic
    raise SystemExit(f"Unknown topic '{name}'. Run: python -m tf_gnns.agent_docs list")


def _extract_examples(text: str) -> str:
    blocks = re.findall(r"```python\n.*?```", text, flags=re.DOTALL)
    return "\n\n".join(blocks)


def _extract_rules(text: str) -> str:
    lines = []
    in_rules = False
    for line in text.splitlines():
        if line == "## Rules":
            in_rules = True
            continue
        if in_rules and line.startswith("## "):
            break
        if in_rules:
            lines.append(line)
    return "\n".join(lines).strip()


def _extract_concepts(text: str) -> str:
    """Extract concept sections (How It Works through Output Contract, before Example Gallery)."""
    lines = text.splitlines()
    start = None
    end = None
    for i, line in enumerate(lines):
        if line.startswith("## How It Works"):
            start = i
        if start is not None and line.startswith("## Example Gallery"):
            end = i
            break
    if start is None:
        return text
    return "\n".join(lines[start:end]).rstrip()


def list_topics(_args: argparse.Namespace) -> int:
    for topic in TOPICS:
        print(f"{topic.name:10} {topic.title} - read when {topic.when}")
    return 0


def get_topic(args: argparse.Namespace) -> int:
    topic = _topic_by_name(args.topic)
    text = _resource_text(topic.path)
    if args.examples:
        text = _extract_examples(text)
    elif args.rules:
        text = _extract_rules(text)
    elif args.concepts:
        text = _extract_concepts(text)
    print(text.rstrip())
    return 0


def _topic_texts() -> list[tuple[Topic, str]]:
    return [(topic, _resource_text(topic.path)) for topic in TOPICS]


def _api_card(entry: dict[str, object]) -> str:
    return (
        f"API {entry['name']}\n"
        f"  import: {entry['import']}\n"
        f"  signature: {entry['signature']}\n"
        f"  summary: {entry['summary']}\n"
        f"  returns: {entry.get('returns') or 'not documented'}\n"
        f"  topic: {entry['topic']}\n"
        f"  covering_example: {entry.get('example') or 'none'}"
    )


def search(args: argparse.Namespace) -> int:
    regex = re.compile(args.regex, flags=re.IGNORECASE)
    hits: list[str] = []

    for entry in _api_index():
        haystack = "\n".join(str(entry.get(key, "")) for key in ("name", "signature", "summary", "returns", "topic"))
        if regex.search(haystack):
            hits.append(_api_card(entry))

    for topic, text in _topic_texts():
        lines = text.splitlines()
        for i, line in enumerate(lines):
            if not regex.search(line):
                continue
            if args.examples_only:
                before = "\n".join(lines[max(0, i - args.context) : i + args.context + 1])
                if "```python" not in before:
                    continue
            start = max(0, i - args.context)
            end = min(len(lines), i + args.context + 1)
            snippet = "\n".join(f"{n + 1}: {lines[n]}" for n in range(start, end))
            hits.append(f"{topic.name}:{i + 1}\n{snippet}")

    per_page = max(1, args.limit)
    pages = max(1, (len(hits) + per_page - 1) // per_page)
    page = min(max(1, args.page), pages)
    start = (page - 1) * per_page
    selected = hits[start : start + per_page]
    print(f"page {page}/{pages} hits {len(hits)}")
    for hit in selected:
        print("\n---")
        print(hit)
    return 0


def install(args: argparse.Namespace) -> int:
    root = Path(args.project_root).resolve()
    destination = root / ".opencode" / "skills" / SKILL_NAME
    if destination.exists():
        if not args.force:
            raise SystemExit(f"Refusing to overwrite {destination}; pass --force")
        shutil.rmtree(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)
    _copy_skill(destination)
    print(destination)
    return 0


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="python -m tf_gnns.agent_docs")
    subparsers = parser.add_subparsers(dest="command", required=True)

    list_parser = subparsers.add_parser("list", help="List available topics")
    list_parser.set_defaults(func=list_topics)

    get_parser = subparsers.add_parser("get", help="Read a topic")
    get_parser.add_argument("topic")
    mode = get_parser.add_mutually_exclusive_group()
    mode.add_argument("--examples", action="store_true")
    mode.add_argument("--rules", action="store_true")
    mode.add_argument("--concepts", action="store_true")
    get_parser.set_defaults(func=get_topic)

    search_parser = subparsers.add_parser("search", help="Search topics and API cards")
    search_parser.add_argument("regex")
    search_parser.add_argument("--limit", type=int, default=10)
    search_parser.add_argument("--page", type=int, default=1)
    search_parser.add_argument("--context", type=int, default=2)
    search_parser.add_argument("--examples-only", action="store_true")
    search_parser.set_defaults(func=search)

    install_parser = subparsers.add_parser("install-opencode-skill", help="Install the packaged skill into a project")
    install_parser.add_argument("--project-root", default=".")
    install_parser.add_argument("--force", action="store_true")
    install_parser.set_defaults(func=install)
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    return args.func(args)


if __name__ == "__main__":  # pragma: no cover
    sys.exit(main())
